using System.Globalization;

namespace WweAllStars.Launcher.Core;

/// <summary>One file the supported disc holds: its path ('/' separators), size and SHA-256.</summary>
public sealed record ManifestEntry(string Path, long Size, string Sha256);

/// <summary>
/// The disc manifest (spec, "Setup pipeline"): every file of the supported disc with its size and
/// SHA-256, no data. Generated by <c>scripts/inspect_disc.py --manifest</c> into
/// <c>launcher/disc-manifest.tsv</c>, which the core embeds. Format: <c>#</c> comments, one
/// <c>manifest_version&lt;TAB&gt;id</c> line, then <c>sha256&lt;TAB&gt;size&lt;TAB&gt;path</c> per file.
/// </summary>
public sealed class DiscManifest
{
    public const string ExecutablePath = "default.xex";

    private readonly Dictionary<string, ManifestEntry> _byPath;

    private DiscManifest(string version, IReadOnlyList<ManifestEntry> files)
    {
        Version = version;
        Files = files;
        _byPath = files.ToDictionary(file => file.Path, StringComparer.OrdinalIgnoreCase);
        Executable = Find(ExecutablePath) ?? throw new InvalidDataException("The disc manifest lists no default.xex.");
    }

    /// <summary>Names the manifest; the setup marker records it.</summary>
    public string Version { get; }
    public IReadOnlyList<ManifestEntry> Files { get; }
    public ManifestEntry Executable { get; }
    public long TotalBytes => Files.Sum(file => file.Size);

    public ManifestEntry? Find(string path) => _byPath.GetValueOrDefault(path);

    /// <summary>The manifest of the disc this build supports (WWE All Stars, Xbox 360, XEX v5).</summary>
    public static DiscManifest Supported { get; } = LoadSupported();

    private static DiscManifest LoadSupported()
    {
        using var stream = typeof(DiscManifest).Assembly.GetManifestResourceStream("disc-manifest.tsv")
            ?? throw new InvalidOperationException("The disc manifest is not embedded in the launcher.");
        using var reader = new StreamReader(stream);
        return Parse(reader.ReadToEnd());
    }

    public static DiscManifest Load(string path) => Parse(File.ReadAllText(path));

    public static DiscManifest Parse(string text)
    {
        var (version, files) = ParseLines(text, "disc manifest");
        return new DiscManifest(version, files);
    }

    /// <summary>
    /// The manifest format (shared with <see cref="TitleUpdateManifest"/>): <c>#</c> comments, one
    /// <c>manifest_version&lt;TAB&gt;id</c> line, then <c>sha256&lt;TAB&gt;size&lt;TAB&gt;path</c> per file.
    /// </summary>
    internal static (string Version, List<ManifestEntry> Files) ParseLines(string text, string what)
    {
        string? version = null;
        var files = new List<ManifestEntry>();
        foreach (var raw in text.Split('\n'))
        {
            var line = raw.TrimEnd('\r');
            if (line.Length == 0 || line[0] == '#') continue;
            var parts = line.Split('\t');
            if (parts is ["manifest_version", var id] && version is null && id.Length > 0) version = id;
            else if (parts.Length == 3 && parts[0].Length == 64
                     && long.TryParse(parts[1], NumberStyles.None, CultureInfo.InvariantCulture, out var size)
                     && parts[2].Length > 0)
                files.Add(new ManifestEntry(parts[2], size, parts[0].ToLowerInvariant()));
            else throw new InvalidDataException($"The {what} has a malformed line: {line}");
        }
        if (version is null) throw new InvalidDataException($"The {what} has no manifest_version line.");
        return (version, files);
    }
}
